<script setup lang="ts">
import { computed, reactive } from 'vue';
import { Activity, ArrowRight, Check, Clock3, Cpu, FileText, Gauge, Play, Plus, Server, Settings2, Square, Zap } from 'lucide-vue-next';
import TrendChart from './TrendChart.vue';
import { phaseName, summarize, type LoadResult, type LoadConfig, type EndpointConfig } from './engine';
const props = defineProps<{ endpoints: EndpointConfig[]; result: LoadResult | null; resultConfig?: LoadConfig; busy: boolean; running: boolean; reportAvailable: boolean }>();
const emit = defineEmits<{ start: [config: LoadConfig]; stop: []; increase: []; report: []; export: [] }>();
const config = reactive<LoadConfig>({ concurrency:1000, duration:60, rps:0, endpointId:'delivery-availability', ...props.resultConfig });
const chartConfig = computed(()=>props.result && props.resultConfig ? props.resultConfig : config);
const stats = computed(()=>summarize(props.result?.samples || [],props.result?.elapsedMs || 0));
const lastFrame = computed(()=>props.result?.frames.at(-1));
const endpoint = computed(()=>props.endpoints.find(e=>e.id===chartConfig.value.endpointId));
const recentEvents = computed(()=>[...(props.result?.events || [])].reverse().slice(0,4));
const number = (value:number,digits=0)=>value.toLocaleString('zh-CN',{maximumFractionDigits:digits});
const canIncrease = computed(()=>props.running && (props.result?.level || 0)<5);
</script>
<template>
  <div class="pressure-workspace">
    <section class="page-heading"><div><div class="eyebrow">SERVICE ENGINEERING / OBSERVABILITY</div><h1>观察系统，如何承受压力。</h1><p>逐级增加并发负载，观察吞吐与延迟如何响应每一次加压。</p></div><button class="secondary" :disabled="busy || !reportAvailable" @click="emit('export')"><FileText :size="16"/>导出最近报告</button></section>
    <div class="context-strip"><span><span class="status-dot"/>智慧校园</span><code>http://localhost:5606</code><span class="context-right">{{endpoints.length}} 个观测接口 · {{running?'测试进行中':result?'本轮记录已保存':'等待手动启动'}}</span></div>
    <section class="metrics" aria-label="测试指标">
      <article><div class="metric-label">当前并发负载<Cpu :size="17"/></div><div class="metric-value">{{result?number(lastFrame?.concurrency || 0):'—'}}<span>/ {{chartConfig.concurrency}}</span></div><div class="metric-foot"><span class="status-dot"/>{{result?phaseName(result.phase):'等待启动'}}<small>第 {{result?.level || 0}} / 5 级</small></div></article>
      <article><div class="metric-label">实时吞吐量<Zap :size="17"/></div><div class="metric-value">{{result?number(lastFrame?.rps || 0,1):'—'}}<span>req/s</span></div><div class="metric-foot">{{chartConfig.rps?`上限 ${number(chartConfig.rps)} req/s`:'按并发与耗时计算'}}<small>当前窗口</small></div></article>
      <article><div class="metric-label">累计完成请求<Check :size="17"/></div><div class="metric-value">{{result?number(stats.count):'—'}}<span>次</span></div><div class="metric-foot"><span class="status-dot"/>{{stats.count?number(stats.successRate,1)+'% 通过率':'准备采样'}}<small>本轮累计</small></div></article>
      <article><div class="metric-label">P95 响应延迟<Activity :size="17"/></div><div class="metric-value">{{lastFrame?.p95?number(lastFrame.p95,1):'—'}}<span>ms</span></div><div class="metric-foot">{{lastFrame?.p50?`P50 ${number(lastFrame.p50,1)} ms`:'等待首个窗口'}}<small>当前窗口</small></div></article>
    </section>
    <div v-if="reportAvailable && !busy" class="load-report-entry"><div><FileText :size="18"/><span>最近一轮压测{{result?.status==='completed'?'已完成':'已停止'}}，报告已保存</span></div><button class="secondary" @click="emit('report')">查看压测报告<ArrowRight :size="14"/></button></div>
    <div class="pressure-layout">
      <section class="panel pressure-config"><div class="panel-heading"><div><h2><Settings2 :size="18"/>负载配置</h2><p>定义本轮测试的目标与节奏</p></div></div><fieldset :disabled="busy"><label>目标接口<select v-model="config.endpointId" aria-label="压测目标接口"><option v-for="item in endpoints" :key="item.id" :value="item.id">{{item.name}} · {{item.path}}</option></select></label><label>目标并发<input v-model.number="config.concurrency" aria-label="目标并发" type="number" min="5" max="1000"/></label><div class="input-pair"><label>测试时长（秒）<input v-model.number="config.duration" aria-label="持续时长" type="number" min="10" max="120"/></label><label>吞吐上限（req/s）<input v-model.number="config.rps" aria-label="吞吐上限" type="number" min="0" max="50000"/></label></div></fieldset><button class="primary full" aria-label="开始压力测试" :disabled="busy || !endpoints.length" @click="emit('start',{...config})"><Play :size="15"/>启动压力测试</button><p v-if="!endpoints.length" class="config-limit">先在API测试中手动生成用例，再选择本轮压测目标。</p><div class="strategy-card"><span class="tiny-tag">STEP LOAD</span><h3>五级递增加压</h3><div class="strategy-steps"><i v-for="level in 5" :key="level" :style="{height:`${10+level*7}px`}"/></div><p>预热后按计划升档，也可随时手动加压。达到目标后保持峰值，直到本轮结束。</p></div><div class="config-limit">并发 5–1,000 · 时长 10–120 s<br/>吞吐上限为 0 时，按并发数与平均响应耗时自动计算；累计完成数按时间累加。</div><button v-if="running" class="secondary full" aria-label="停止压测" @click="emit('stop')"><Square :size="13"/>停止测试</button><div class="config-system"><Server :size="15"/><div>智慧校园<code>http://localhost:5606</code></div></div></section>
      <div class="pressure-observation">
        <section class="panel load-chart-panel"><div class="panel-heading"><div><h2><Gauge :size="19"/>负载与吞吐</h2><p>并发负载逐级抬升，观察每秒请求完成量的变化</p></div><div class="pressure-main-actions"><span class="phase-badge" :class="{running}"><span class="status-dot"/>{{result?phaseName(result.phase):'等待启动'}}</span><button class="boost-button" :disabled="!canIncrease" @click="emit('increase')"><Plus :size="17"/>加压一级</button></div></div><div class="pressure-stage"><div><small>当前负载阶段</small><strong>第 <b>{{result?.level || 0}}</b> / 5 级</strong></div><div class="stage-stair"><span v-for="level in 5" :key="level" :class="{active:(result?.level || 0)>=level}"><i :style="{height:`${9+level*6}px`}"/><small>{{Math.round(chartConfig.concurrency*level/5)}}</small></span></div><div class="stage-time"><strong>{{number((result?.elapsedMs || 0)/1000,1)}}<small> / {{chartConfig.duration}} s</small></strong><span>{{result?.status==='completed'?'本轮已完成':result?.status==='stopped'?'保留停止时曲线':result?'逐级接近目标负载':'等待手动启动'}}</span></div></div><TrendChart kind="load" :frames="result?.frames || []" :events="result?.events || []" :duration="chartConfig.duration" :concurrency="chartConfig.concurrency" :rps="chartConfig.rps" label="本轮负载与吞吐趋势"/><div class="chart-footer"><span class="chart-legend"><i/>并发负载 <i class="amber-line"/>实时吞吐量</span><span>左轴：并发 · 右轴：req/s · ＋：手动加压</span></div></section>
        <section class="panel latency-live-panel"><div class="panel-heading"><div><h2><Activity :size="18"/>响应延迟趋势</h2><p>随负载升高与加压事件变化的窗口分位数</p></div><div class="inline-percentiles"><span>P50 <b>{{lastFrame?.p50?number(lastFrame.p50,1):'—'}}</b></span><span>P95 <b>{{lastFrame?.p95?number(lastFrame.p95,1):'—'}}</b></span><span>P99 <b>{{lastFrame?.p99?number(lastFrame.p99,1):'—'}}</b><small> ms</small></span></div></div><TrendChart :frames="result?.frames || []" :duration="chartConfig.duration" :latency-max="endpoint?.budget || 500" compact label="本轮响应延迟趋势"/><div class="chart-footer"><span class="chart-legend"><i/>P50 <i class="light-line"/>P95</span><span>响应预算 {{endpoint?.budget || 500}} ms</span></div></section>
        <section class="event-strip load-event-list" aria-label="加压事件"><span><Clock3 :size="14"/>加压事件</span><p v-if="!recentEvents.length">计划升档和手动加压将在这里留痕</p><span v-for="event in recentEvents" :key="event.id" class="event-chip" :class="{manual:event.type==='manual'}">{{event.second.toFixed(1)}} s · {{event.type==='manual'?'手动':'计划'}} → {{event.level}} 级</span></section>
      </div>
    </div>
  </div>
</template>
